-- F-346: GitHub webhook 投递先落持久面再回 200。
-- github_app_deliveries 原为"处理完成后落一条幂等记录",崩溃/异步失败会永久丢事件;
-- 新增 payload 保存认领时的可恢复载荷(渲染后的触发规则)。
-- 回滚:ALTER TABLE "github_app_deliveries" DROP COLUMN IF EXISTS "payload";
-- 存量转换:历史行 payload 为 NULL,不影响既有幂等判定;新写入由应用侧填充。
ALTER TABLE "github_app_deliveries" ADD COLUMN IF NOT EXISTS "payload" jsonb;
